import {providerName,endpointProviderIds} from '/providers.js';
import {libraryIcon} from '/agent-appearance.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={ollama:'http://127.0.0.1:11434/v1',llamacpp:'http://127.0.0.1:8080/v1',lmstudio:'http://127.0.0.1:1234/v1'};
const kinds=['ollama','llamacpp','lmstudio','bedrock','sagemaker','jev','codex-summary','claude-summary'];
const button=(action,label,extra='')=>`<button type="button" data-ai="${action}" ${extra}>${label}</button>`;

export async function mountAISettings(host,{api,onSaved,initialKind,onClose,connectionOnly=false}){
  host.aiSettingsAbort?.abort();const controller=new AbortController();host.aiSettingsAbort=controller;const signal=controller.signal;
  let data=await api('ai-connections'),editing=null,busy=false,discovered=[];
  const tests=new Map();
  if(!host.isConnected)return;
  function feedback(text,error=false){const node=host.querySelector('.ai-feedback');if(node){node.textContent=text;node.classList.toggle('form-error',error);}}
  function testResult(id){const result=tests.get(id);return result?`<span class="ai-test-icon" aria-hidden="true">${libraryIcon({pending:'loader',success:'circle-check',error:'circle-alert'}[result.state],18)}</span><span>${esc(result.text)}</span>`:'';}
  function testFeedback(id,state,text){
    tests.set(id,{state,text});
    const card=[...host.querySelectorAll('[data-connection-id]')].find(node=>node.dataset.connectionId===id),node=card?.querySelector('.ai-connection-feedback');
    if(node){node.dataset.state=state;node.innerHTML=testResult(id);}
  }
  async function pairContext(jevId,summaryId){
    data=await api('ai-connections');
    let summary=data.connections.find(c=>c.id===summaryId&&c.enabled&&c.kind!=='jev'&&c.model);
    if(['native-codex','native-claude'].includes(summaryId)){
      const kind=summaryId==='native-claude'?'claude-summary':'codex-summary',model=summaryId==='native-claude'?'claude-sonnet-5':'gpt-6-luna';
      summary=data.connections.find(c=>c.kind===kind&&c.enabled&&c.model===model);
      if(!summary)summary=await api('ai-connections',{kind,name:(kind==='claude-summary'?'Claude Sonnet':'Codex Luna')+' · context summaries',model,contextWindow:64000,maxOutputTokens:2048,supportsTools:false,enabled:true});
    }
    if(!summary)throw Error('Choose a language model for checkpoint summaries.');
    data=await api('ai-connections');render();testFeedback(summary.id,'pending','Testing summary model…');
    try{const result=await api('ai-connections/test',{id:summary.id});testFeedback(summary.id,'success',`Connected · ${result.model||summary.model}`);}
    catch(error){data=await api('ai-connections');render();testFeedback(summary.id,'error',`Connection failed · ${error.message}`);throw error;}
    await api('context/settings',{...data.settings,decisionConnectionId:jevId,summaryConnectionId:summary.id,expectedRevision:data.settings.revision});
    data=await api('ai-connections');
  }
  function render(){
    if(!host.isConnected)return;
    const settings=data.settings,connections=data.connections,archived=data.archivedConnections||[];
    host.innerHTML=`<section class="ai-settings"><div class="ai-intro"><div><span class="eyebrow">CONNECTED INTELLIGENCE</span><h3>Local AI & Model Connections</h3><p>Connect several models on this computer, another machine, or AWS. Choose the connection independently for each agent. Connections and context defaults apply across your projects. For LM Studio, start its local API server, then add a connection and discover your loaded model.</p></div>${button('new',libraryIcon('plus',16)+' Add connection','class="primary"')}</div>
      <div class="ai-connection-grid">${connections.map(c=>`<article class="ai-connection ${c.enabled?'':'is-disabled'}" data-connection-id="${esc(c.id)}"><span class="resource-icon">${libraryIcon(c.kind==='jev'?'git-branch':c.baseUrl?'database':'globe',23)}</span><div><h4>${esc(c.name)}</h4><p>${esc(providerName(c.kind))} · ${esc(c.location||c.region||(c.kind.endsWith('-summary')?'Signed-in CLI account':'TypeSafe API'))}</p><small>${esc(c.model||'Choose a model per agent')}</small><div class="resource-labels"><span>${c.enabled?'Enabled':'Disabled'}</span><span>${c.kind==='jev'?'Context + memory ranking':c.supportsTools?'Agents + summaries':'Summaries'}</span></div></div><footer>${button('edit','Manage',`data-id="${c.id}"`)}${button('test','Test connection',`data-id="${c.id}" ${c.enabled?'':'disabled'}`)}${c.baseUrl?button('archive','Archive',`data-id="${c.id}"`):''}</footer><div class="ai-connection-feedback" data-state="${tests.get(c.id)?.state||''}" role="status" aria-label="${esc(c.name)} connection test" aria-live="polite" aria-atomic="true">${testResult(c.id)}</div></article>`).join('')||'<div class="settings-empty">Your existing Codex, Claude Code, and Kiro sessions are ready as before. Add a model connection here to use local or AWS models, or connect Jev for context decisions.</div>'}</div>
      ${archived.length?`<details class="ai-archived"><summary>Archived Connections (${archived.length})</summary><p>These connections are hidden from the pickers. Their settings and saved keys are kept so you can restore them.</p>${archived.map(c=>`<div class="ai-archived-row"><span><strong>${esc(c.name)}</strong><small>${esc(c.model)}</small></span>${button('restore','Restore',`data-id="${c.id}"`)}</div>`).join('')}</details>`:''}
      <details class="ai-help"><summary>${libraryIcon('globe',16)} Using another computer or more than one server</summary><p><code>localhost</code> always means the computer running HeloScrum’s backend. Use the other machine’s reachable LAN/VPN address, or a tunnel with a distinct local port. You can save several connections to the same server and choose different models.</p><p>Model inference runs at that address. Files, tool execution, and agent permissions stay with this HeloScrum backend. Use authenticated connections or a trusted private network; HeloScrum does not expose or start model servers for you.</p><p>Cursor CLI uses its own account and model catalog. Install <code>cursor-agent</code> and sign in, or set <code>HELOSCRUM_CURSOR_BIN</code> to its executable, then restart HeloScrum. Cursor’s native sandbox and MCP permissions apply.</p></details>
      ${connections.some(c=>c.kind==='jev'&&c.enabled)&&(!settings.decisionConnectionId||!settings.summaryConnectionId)?`<section class="ai-setup-callout"><div><strong>Finish checkpoint setup</strong><p>Jev assesses context. A separate language model writes the checkpoint. Select a summary model below, or use an existing signed-in CLI account. This setup applies across projects.</p></div><div class="ai-pair-actions">${data.summaryProviders?.codex?button('pair','Pair with Luna','data-summary="native-codex"'):''}${data.summaryProviders?.claude?button('pair','Pair with Sonnet','data-summary="native-claude"'):''}</div></section>`:''}
      <form class="ai-context-form"><div class="settings-subheading"><div><h3>Keep working context focused</h3><p class="settings-note">Jev recommends when to checkpoint. A language model writes the summary. Full records remain retrievable.</p></div></div><div class="form-pair"><label>Decision model<select name="decisionConnectionId"><option value="">Rules only · no AI call</option>${connections.filter(c=>c.kind==='jev'&&c.enabled).map(c=>`<option value="${c.id}" ${settings.decisionConnectionId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Summary model<select name="summaryConnectionId"><option value="">Select a model to enable checkpoints</option>${connections.filter(c=>c.kind!=='jev'&&c.enabled&&c.model).map(c=>`<option value="${c.id}" ${settings.summaryConnectionId===c.id?'selected':''}>${esc(c.name)} · ${esc(c.model)}</option>`).join('')}</select></label></div><div class="form-pair"><label>Working context budget (estimated tokens)<input type="number" name="budgetTokens" min="4096" max="256000" required value="${settings.budgetTokens}"></label><label>Tool preview limit (characters)<input type="number" name="toolResultChars" min="2000" max="24000" required value="${settings.toolResultChars}"></label></div><p class="settings-note">Local and AWS agent sessions compact at the budget, retaining complete tool exchanges. Native CLI sessions use a reviewed checkpoint from Agent settings. Jev uses a small state snapshot near the local/AWS context budget. Native CLI assessments run when requested. Selecting a remote summary or decision service sends the displayed type of records to that service.</p><label class="ai-memory-ranking"><input type="checkbox" name="memoryRankingEnabled" ${settings.memoryRankingEnabled?'checked':''}> Rank memory search with Jev</label><p class="settings-note">Sends the query and up to 12 accessible passages to the decision model. Exact references stay first. Local search is used when ranking is unavailable; each search can also use local only.</p><footer><button class="primary" type="submit">Save context settings</button></footer></form><p class="ai-feedback" role="status" aria-live="polite"></p></section>`;
  }
  function editor(c={kind:'ollama',contextWindow:32768,maxOutputTokens:4096,enabled:true,supportsTools:false}){
    editing=c;discovered=[];const local=!!defaults[c.kind],aws=['bedrock','sagemaker'].includes(c.kind),jev=c.kind==='jev',native=c.kind.endsWith('-summary');
    host.innerHTML=`<section class="ai-settings">${button('back',connectionOnly?'← Back To Your Agent':'← All Connections','class="settings-back"')}<h3>${c.id?'Manage connection':'Add an AI connection'}</h3><form class="ai-connection-form"><div class="form-pair"><label>Connection name<input name="name" required maxlength="80" value="${esc(c.name)}" placeholder="Mac Studio · coding model"></label><label>Service<select name="kind" ${c.id?'disabled':''}>${(connectionOnly?kinds.filter(k=>endpointProviderIds.includes(k)):kinds).map(k=>`<option value="${k}" ${k===c.kind?'selected':''}>${esc(providerName(k))}</option>`).join('')}</select></label></div>
      ${local?`<label>API base URL<input name="baseUrl" type="url" required value="${esc(c.baseUrl||defaults[c.kind])}" placeholder="http://192.168.1.40:11434/v1"></label><p class="settings-note">Include the <code>/v1</code> path. Each machine or forwarded port can be saved as its own connection.</p>`:''}
      ${native?'<p class="settings-note">Uses the signed-in CLI account with a fresh, temporary summary session and low reasoning effort. Project records are sent to the selected provider. No separate API key is needed.</p>':aws?`<div class="form-pair"><label>AWS region<input name="region" required value="${esc(c.region||'us-east-1')}" placeholder="us-east-1"></label><label>AWS profile (optional)<input name="profile" value="${esc(c.profile)}" placeholder="Default AWS credential chain"></label></div>${c.kind==='sagemaker'?`<label>SageMaker endpoint name<input name="endpointName" required maxlength="63" value="${esc(c.endpointName)}"></label><p class="settings-note">Uses InvokeEndpoint with an OpenAI Chat Completions JSON body. Your container must accept that body at /invocations and return choices[].message, including tool_calls for agents. Arbitrary custom endpoint schemas are not supported.</p>`:'<p class="settings-note">Uses the Bedrock Converse API. Enter a supported model ID or inference profile ID/ARN. The selected AWS profile needs invoke permission.</p>'}<p class="settings-note">Uses your installed AWS CLI and saved profile/SSO session. AWS credentials are never entered here.</p>`:`<label>${jev?'TypeSafe API key':'API key (optional)'}<input name="apiKey" type="password" autocomplete="new-password" value="" placeholder="${c.hasKey?'Saved · leave blank to keep':'Stored privately on the backend'}"></label>${c.hasKey?'<label class="settings-check"><input type="checkbox" name="clearKey">Remove saved key</label>':''}`}
      <label>${jev?'Jev model':'Default model ID'}<input name="model" ${!local?'required':''} maxlength="150" value="${esc(c.model||(jev?'jev-latest':''))}" placeholder="Exact model ID from your server" list="ai-model-list"></label><datalist id="ai-model-list"></datalist>${local?button('discover','Discover Models')+'<label data-discovered-field hidden>Available Models<select name="discoveredModel"></select></label>':''}
      ${jev?'<p class="settings-note">Jev returns typed decisions and confidence scores. It does not generate summaries. Pair it with a language model in context settings.</p>':`<div class="form-pair"><label>Model context window<input name="contextWindow" type="number" min="4096" max="2000000" required value="${c.contextWindow}"></label><label>Maximum output tokens<input name="maxOutputTokens" type="number" min="256" max="32768" required value="${c.maxOutputTokens}"></label></div>${native?'':`<label class="settings-check"><input type="checkbox" name="supportsTools" ${c.supportsTools?'checked':''}>This model supports function/tool calling · allow agent sessions</label><label class="settings-check"><input type="checkbox" name="supportsImages" ${c.supportsImages?'checked':''}>This model supports image input · allow image attachments</label>`}<p class="settings-note">Leave unchecked for summary-only models. ${native?'This connection generates text summaries only. The context window limits the records submitted per request.':'Match the context window to the server’s actual configuration. Local models vary in tool support and quality.'}</p>`}
      ${jev&&!c.id?`<label>Checkpoint summary model<select name="pairedSummaryId" required><option value="">Select a language model</option>${data.summaryProviders?.codex?'<option value="native-codex" selected>Signed-in Codex · GPT 6 Luna · low effort</option>':''}${data.summaryProviders?.claude?'<option value="native-claude">Signed-in Claude Code · Sonnet 5 · low effort</option>':''}${data.connections.filter(x=>x.kind!=='jev'&&x.enabled&&x.model).map(x=>`<option value="${x.id}" ${data.settings.summaryConnectionId===x.id?'selected':''}>${esc(x.name)} · ${esc(x.model)}</option>`).join('')}</select></label><p class="settings-note">Saving tests the summary model and enables this pair for context management across projects. If no model is available, add a summary connection first.</p>`:''}
      <label class="settings-check"><input type="checkbox" name="connectionEnabled" ${c.enabled?'checked':''}>Enabled</label><p class="settings-note">Connection tests make a small inference request. Adding or editing a connection alone does not send project content.</p><footer class="project-resource-actions">${button('back','Cancel')}<button type="submit" class="primary">Save connection</button></footer></form><p class="ai-feedback" role="status" aria-live="polite"></p></section>`;
  }
  async function work(fn,onError=error=>feedback(error.message,true)){if(busy)return;busy=true;host.setAttribute('aria-busy','true');const controls=[...host.querySelectorAll('button,input,select')].map(e=>[e,e.disabled]);controls.forEach(([e])=>e.disabled=true);try{await fn();}catch(e){onError(e);}finally{busy=false;host.removeAttribute('aria-busy');controls.forEach(([e,d])=>{if(e.isConnected)e.disabled=d;});}}
  host.addEventListener('click',event=>{const target=event.target.closest('[data-ai]');if(!target)return;event.stopPropagation();if(busy)return;const action=target.dataset.ai,id=target.dataset.id;
    if(action==='archive'||action==='restore')return work(async()=>{const saved=[...data.connections,...(data.archivedConnections||[])].find(c=>c.id===id);await api('ai-connections/archive',{id,expectedRevision:saved.revision,restore:action==='restore'});data=await api('ai-connections');render();feedback(action==='restore'?'Connection restored.':'Connection archived. You can restore it below.');await onSaved?.();});
    if(action==='pair')return work(async()=>{feedback('Setting up and testing the summary model…');const jev=data.connections.find(c=>c.id===data.settings.decisionConnectionId)||data.connections.find(c=>c.kind==='jev'&&c.enabled);await pairContext(jev.id,target.dataset.summary);render();feedback('Jev and checkpoint summaries are ready.');await onSaved?.();});
    if(action==='new')return editor();if(action==='back'){if(connectionOnly)return onClose?.();editing=null;render();return;}if(action==='edit')return editor(data.connections.find(c=>c.id===id));
    if(action==='discover'){
      const form=host.querySelector('.ai-connection-form'),draft=Object.fromEntries(new FormData(form));
      return work(async()=>{
        feedback('Checking the model server…');const result=await api('ai-connections/models',{id:editing.id,kind:editing.kind,baseUrl:draft.baseUrl,apiKey:draft.apiKey,clearKey:!!draft.clearKey,model:draft.model});discovered=result.models;
        host.querySelector('#ai-model-list').innerHTML=discovered.map(m=>`<option value="${esc(m.id)}">`).join('');
        const field=host.querySelector('[data-discovered-field]'),select=form.elements.discoveredModel;field.hidden=!discovered.length;
        select.innerHTML='<option value="">Choose A Model</option>'+discovered.map(m=>`<option value="${esc(m.id)}">${esc(m.label||m.id)}${m.loaded?' · Loaded':''} · ${esc(m.id)}</option>`).join('');
        const loaded=discovered.filter(m=>m.loaded),chosen=discovered.find(m=>m.id===draft.model)||(!draft.model&&(loaded.length===1?loaded[0]:discovered.length===1?discovered[0]:null));
        if(chosen){select.value=chosen.id;chooseModel(chosen.id);}
        feedback(discovered.length?`Server connected. ${discovered.length} models available${loaded.length?`, ${loaded.length} loaded`:''}. ${chosen?'Model details filled from the server. Review them, then save.':'Choose a model below.'}`:'Server connected, but no language models were found. Load a model in your model app, then discover again.');
      },error=>feedback(`Couldn’t read the model server. Check that its API server is running and the address is correct. ${error.message}`,true));
    }
    if(action==='test')work(async()=>{
      feedback('');testFeedback(id,'pending','Testing connection…');target.setAttribute('aria-busy','true');
      try{const result=await api('ai-connections/test',{id});testFeedback(id,'success',`Connected · ${result.model||'model response received'}${result.reply?' · '+result.reply:''}`);}
      finally{target.removeAttribute('aria-busy');}
    },error=>testFeedback(id,'error',`Connection failed · ${error.message}`));
  },{signal});
  host.addEventListener('change',event=>{event.stopPropagation();if(event.target.name==='discoveredModel')chooseModel(event.target.value);if(event.target.name==='kind'){const form=event.target.form,draft=Object.fromEntries(new FormData(form));editor({...editing,...draft,enabled:!!draft.connectionEnabled,supportsTools:!!draft.supportsTools,supportsImages:!!draft.supportsImages,kind:event.target.value,model:'',baseUrl:undefined});}if(event.target.name==='model'){const selected=host.querySelector('[name=discoveredModel]');if(selected)selected.value=event.target.value;}} ,{signal});
  host.addEventListener('submit',event=>{event.preventDefault();event.stopPropagation();const form=event.target,values=Object.fromEntries(new FormData(form));work(async()=>{
    feedback('Saving…');let savedNotice='Settings saved.';
    if(form.classList.contains('ai-connection-form')){const body={...values,kind:editing.kind,...(editing.id?{id:editing.id,expectedRevision:editing.revision}:{}),enabled:!!values.connectionEnabled,supportsTools:!!values.supportsTools,supportsImages:!!values.supportsImages,clearKey:!!values.clearKey,contextWindow:Number(values.contextWindow||32768),maxOutputTokens:Number(values.maxOutputTokens||4096)};const saved=await api('ai-connections',body);if(saved.reused)savedNotice='Using your existing connection; no duplicate was created.';if(connectionOnly){await onSaved?.(saved);return;}tests.delete(editing.id);const pair=editing.kind==='jev'&&!editing.id;editing=null;if(pair)await pairContext(saved.id,values.pairedSummaryId);}
    else await api('context/settings',{memoryRankingEnabled:form.elements.memoryRankingEnabled.checked,decisionConnectionId:values.decisionConnectionId,summaryConnectionId:values.summaryConnectionId,budgetTokens:Number(values.budgetTokens),toolResultChars:Number(values.toolResultChars),expectedRevision:data.settings.revision});
    data=await api('ai-connections');render();feedback(savedNotice);await onSaved?.();
  });},{signal});
  function chooseModel(id){
    const model=discovered.find(m=>m.id===id),form=host.querySelector('.ai-connection-form');if(!model||!form)return;
    form.elements.model.value=model.id;
    if(Number.isInteger(model.contextWindow)&&model.contextWindow>=4096&&model.contextWindow<=2000000){form.elements.contextWindow.value=model.contextWindow;if(Number(form.elements.maxOutputTokens.value)>=model.contextWindow)form.elements.maxOutputTokens.value=Math.min(4096,Math.floor(model.contextWindow/4));}
    if(typeof model.supportsTools==='boolean')form.elements.supportsTools.checked=model.supportsTools;
    if(typeof model.supportsImages==='boolean')form.elements.supportsImages.checked=model.supportsImages;
  }
  if(initialKind)editor({kind:initialKind,name:providerName(initialKind),contextWindow:32768,maxOutputTokens:4096,enabled:true,supportsTools:false});else render();
}

export async function openAIConnectionDialog(trigger,{api,kind='lmstudio',onSaved}){
  const dialog=document.createElement('dialog');dialog.className='project-settings-dialog ai-connection-dialog';dialog.setAttribute('aria-label','Set Up '+providerName(kind));
  dialog.innerHTML=`<header class="project-settings-head"><h2>Set Up ${esc(providerName(kind))}</h2><button type="button" data-close-connection aria-label="Close connection setup">×</button></header><div class="project-settings-body"><p role="status">Loading connections…</p></div>`;
  document.body.append(dialog);dialog.showModal();const host=dialog.querySelector('.project-settings-body');
  const close=()=>{if(host.getAttribute('aria-busy')==='true')return;host.aiSettingsAbort?.abort();dialog.close();dialog.remove();if(trigger?.isConnected)trigger.focus();};
  dialog.addEventListener('cancel',event=>{event.preventDefault();close();});dialog.querySelector('[data-close-connection]').addEventListener('click',close);
  try{await mountAISettings(host,{api,initialKind:kind,connectionOnly:true,onClose:close,onSaved:async connection=>{await onSaved?.(connection);host.removeAttribute('aria-busy');close();}});}catch(error){host.textContent=error.message;}
}
